문 10. 다음 C++ 프로그램의 실행 결과가 아래와 같이 나오기 위해
㉠에서 구현해야 하는 생성자 코드로 옳은 것은?
#include <iostream>
#include <string.h>
using std::cout;
using std::endl;
class A {
char *str;
public:
A() { str = NULL; }
㉠
A(char *ss) {
str = new char[strlen(ss)+1];
strcpy(str, ss);
}
void set(char *cc) { strcpy(str, cc); }
void show() { cout << str << endl; }
};
void main() {
A a("AAAA");
A b = a;
a.set("BBBB");
a.show();
b.show();
}
<실행 결과>
BBBB
AAAA

choices:
A(A a) {
str = new char[strlen(a.str)+1];
strcpy(str, a.str);
}

A(A *a) {
str = new char[strlen(a->str)+1];
strcpy(str, a->str);
}

A(A &a) {
str = new char[strlen(a.str)+1];
strcpy(str, a.str);
}

A(char *a) {
str = new char[strlen(a)+1];
strcpy(str, a);
}

