문 18. 다음 C++ 프로그램의 실행 결과로 옳은 것은?
#include <iostream>
using std::cout;
class A {
public:
virtual void p() { cout << "A.p "; }
void q() { cout << "A.q "; }
virtual void r() {
p();
q();
}
};
class B : public A {
public:
void p() { cout << "B.p "; }
};
class C : public B {
public:
void q() { cout << "C.q "; }
void r() {
q();
p();
}
};
void main() {
A *ap = new B;
ap->r();
ap = new C;
ap->r();
}

문 19. 다음 Java 프로그램의 실행결과로 옳은 것은?
class A extends RuntimeException { };
class B extends A { };
class Test {
public static void main(String[] args) {
try {
try {
throw new B();
} catch (A x) {
System.out.print("1 ");
throw x;
} finally {
System.out.print("2 ");
}
} catch (B x) {
System.out.print("3 ");
}
}
}

문 20. 다음 C 프로그램의 실행 결과로 옳은 것은?
#include <stdio.h>
unsigned int getbits(unsigned x, int p, int n) {
return (x >> (p - n)) & ~(~0 << n);
}
void main() {
unsigned int x = 312, res;
res = getbits(x, 8, 4);
printf("%d\n", res);
}
